<script setup lang="ts">const props=defineProps<{frames:string[];alt:string}>();const frame=ref(0),start=ref(0);const {c}=useCopy();function move(e:PointerEvent){if(!e.buttons)return;const delta=e.clientX-start.value;if(Math.abs(delta)>12){frame.value=(frame.value+(delta>0?1:-1)+props.frames.length)%props.frames.length;start.value=e.clientX}}function down(e:PointerEvent){start.value=e.clientX;(e.target as HTMLElement).setPointerCapture(e.pointerId)}
</script><template><div v-if="frames.length>=8&&frames.length<=24" class="spinner"><img :src="frames[frame]" :alt="alt" width="700" height="900" draggable="false" style="touch-action:pan-y" @pointerdown="down" @pointermove="move"/><div class="hero-ctas"><button class="button button-secondary" :aria-label="c('تدوير للخلف','Rotate previous')" @click="frame=(frame-1+frames.length)%frames.length">{{c('السابق','Previous')}}</button><span>{{c('اسحب للتدوير','Drag to rotate')}}</span><button class="button button-secondary" :aria-label="c('تدوير للأمام','Rotate next')" @click="frame=(frame+1)%frames.length">{{c('التالي','Next')}}</button></div></div></template>
